l: 'Example field 3', type: 'file', file_type: 'jpeg', placeholder: 'Enter field 3', validation_status: 0, option: [] }\n      ]\n\n      formFields.value = formFields1 // Set directly\n      setFormData(defaultData())\n    }\n  }\n)\n\n// Reload Datatable, SnackBar Message, Alert, Offcanvas Close\nconst reset_datatable_close_offcanvas = (res) => {\n  if (res.status) {\n    window.successSnackbar(res.message)\n    bootstrap.Modal.getInstance('#exampleModal').hide()\n  } else {\n    window.errorSnackbar(res.message)\n    errorMessages.value = res.all_message\n  }\n\n  window.location.reload()\n\n  emit('onSubmit')\n}\n\n// Form Submit\nconst formSubmit = handleSubmit((values) => {\n  if (!formFields.value.length) {\n    window.errorSnackbar('Form fields cannot be empty!')\n    return\n  }\n\n  values.formFields = JSON.stringify(formFields.value)\n  values.show_in = JSON.stringify(show_in.value)\n  values.appointment_status = JSON.stringify(appiontment_status.value)\n\n  if (currentId.value > 0) {\n    updateRequest({ url: UPDATE_URL, id: currentId.value, body: values }).then((res) => reset_datatable_close_offcanvas(res))\n  } else {\n    storeRequest({ url: STORE_URL, body: values }).then((res) => reset_datatable_close_offcanvas(res))\n  }\n})\n</script>\n\n<style scoped>\n.form-container {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 10px;\n}\n\n.form-field {\n  border: 1px solid #ddd;\n  padding: 10px;\n  background: #f9f9f9;\n  border-radius: 5px;\n  position: relative;\n}\n\n.delete-icon {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  cursor: pointer;\n}\n\n.delete-icon:hover {\n  color: red;\n}\n\n.field-label {\n  cursor: pointer;\n  display: inline-block;\n  padding: 5px;\n  font-weight: bold;\n  color: #000000;\n}\n\n.field-label:hover {\n  text-decoration: underline;\n}\n\n.input-group {\n  margin-bottom: 10px;\n}\n\n.icon-container {\n  top: 10px;\n  right: 10px;\n}\n\n.edit-icon,\n.delete-icon {\n  cursor: pointer;\n}\n\n.e